from docx import Document
from openpyxl import load_workbook
from pathlib import Path
for p in Path('/documents').iterdir():
 print('\n###',p.name)
 if p.suffix=='.docx':
  d=Document(p)
  for para in d.paragraphs:
   if para.text.strip(): print(para.text)
  for ti,t in enumerate(d.tables):
   print('TABLE',ti)
   for row in t.rows: print(' | '.join(c.text for c in row.cells))
 elif p.suffix=='.xlsx':
  w=load_workbook(p,data_only=False)
  for s in w:
   print('SHEET',s.title,s.max_row,s.max_column)
   for row in s.iter_rows(values_only=True): print(row)
